pm.test("Every company is within the returned search radius", () => {
  const centre = res.searchLocation;
  const radians = value => value * Math.PI / 180;
  res.data.forEach(company => {
    pm.expect(company.location.type).to.eql("Point");
    const [lng, lat] = company.location.coordinates;
    const a = Math.sin(radians(lat - centre.latitude) / 2) ** 2 + Math.cos(radians(centre.latitude)) * Math.cos(radians(lat)) * Math.sin(radians(lng - centre.longitude) / 2) ** 2;
    const distanceKm = 6378.1 * 2 * Math.asin(Math.sqrt(Math.min(1, a)));
    pm.expect(distanceKm).to.be.at.most(centre.radiusKm + 0.001);
  });
});

